// Code node "Config": settings, feed lookup and cache lookup.
// Change the three constants below to match your setup.

const BASE_URL = 'https://n8n.home.arpa/webhook/dithmarschen'; // public URL of this workflow's webhook, no trailing slash
const USER_AGENT = 'dithmarschen-feed-bot (contact: services+bots@ture.dev)';
const CACHE_MINUTES = 45;
const MAX_CACHE_ENTRIES = 30; // the ?ort= value creates one cache entry per value

const FEEDS = {
  pressemitteilungen: {
    url: 'https://www.dithmarschen.de/aktuelles/pressemitteilungen',
    layout: 'news',
    hrefPart: '/pressemitteilungen/details/news/',
    title: 'Kreis Dithmarschen: Pressemitteilungen (inoffiziell)',
    description: 'Inoffizieller Feed. Erzeugt aus der ersten Seite der Pressemitteilungen auf dithmarschen.de.',
  },
  bekanntmachungen: {
    url: 'https://www.dithmarschen.de/aktuelles/bekanntmachungen',
    layout: 'news',
    hrefPart: '/fileadmin/download/aktuelles/bekanntmachungen/',
    yearFromPath: true,
    title: 'Kreis Dithmarschen: Bekanntmachungen (inoffiziell)',
    description: 'Inoffizieller Feed. Erzeugt aus der ersten Seite der Bekanntmachungen auf dithmarschen.de. Die Links führen direkt zu PDF-Dateien.',
  },
  ausschreibungen: {
    url: 'https://www.dithmarschen.de/aktuelles/ausschreibungen',
    layout: 'tender',
    hrefPart: '/fileadmin/download/aktuelles/ausschreibungen/',
    title: 'Kreis Dithmarschen: Ausschreibungen (inoffiziell)',
    description: 'Inoffizieller Feed. Hinweis: Viele Ausschreibungen erscheinen nur auf dem Vergabeportal subreport. Dieser Feed ist deshalb unvollständig.',
  },
  terminkalender: {
    url: 'https://www.dithmarschen.de/aktuelles/terminkalender',
    layout: 'event',
    hrefPart: '/terminkalender/ansicht/',
    title: 'Kreis Dithmarschen: Terminkalender (inoffiziell)',
    description: 'Inoffizieller Feed. Zeigt die ersten Termine der Liste auf dithmarschen.de. Das Datum der Meldung ist der Zeitpunkt, an dem der Termin zuerst in der Liste stand. Der Termin selbst steht im Titel.',
  },
};

// Each feed has its own Webhook node (path dithmarschen/<feed>). Find the one that ran.
const feed = Object.keys(FEEDS).find((key) => $(`Webhook ${key}`).isExecuted);
const ort = (($input.first().json.query || {}).ort || '').trim().slice(0, 40);
const cfg = FEEDS[feed];

if (!cfg) {
  return [{ json: { needsFetch: false, status: 404, contentType: 'text/plain; charset=utf-8', body: `Unknown feed. Use one of: ${Object.keys(FEEDS).join(', ')}\n` } }];
}

const cacheKey = feed + (ort ? `?ort=${ort.toLowerCase()}` : '');
const cache = $getWorkflowStaticData('global').cache || {};
const hit = cache[cacheKey];

if (hit && Date.now() - hit.timestamp < CACHE_MINUTES * 60000) {
  return [{ json: { needsFetch: false, status: 200, contentType: 'application/rss+xml; charset=utf-8', body: hit.xml } }];
}

return [{
  json: {
    needsFetch: true,
    feed, ort, cacheKey, cfg,
    url: cfg.url,
    userAgent: USER_AGENT,
    feedUrl: `${BASE_URL}/${feed}${ort ? `?ort=${encodeURIComponent(ort)}` : ''}`,
    maxCacheEntries: MAX_CACHE_ENTRIES,
  },
}];

// Pure functions: parse the dithmarschen.de list pages and build RSS 2.0.
// No n8n globals are used here, so test.js can run this file in plain Node.
// build.js pastes this file into the "Build feed" Code node.

const SITE = 'https://www.dithmarschen.de';

const MONTHS = { Jan: 1, Feb: 2, 'Mär': 3, Apr: 4, Mai: 5, Jun: 6, Jul: 7, Aug: 8, Sep: 9, Okt: 10, Nov: 11, Dez: 12 };

const NAMED_ENTITIES = {
  amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', hellip: '…', ndash: '–', mdash: '—',
  auml: 'ä', ouml: 'ö', uuml: 'ü', Auml: 'Ä', Ouml: 'Ö', Uuml: 'Ü', szlig: 'ß',
  laquo: '«', raquo: '»', bdquo: '„', ldquo: '“', rdquo: '”', lsquo: '‘', rsquo: '’',
};

function decodeEntities(s) {
  return s.replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (m, e) => {
    if (e[0] === '#') {
      const code = e[1].toLowerCase() === 'x' ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10);
      return String.fromCodePoint(code);
    }
    return Object.prototype.hasOwnProperty.call(NAMED_ENTITIES, e) ? NAMED_ENTITIES[e] : m;
  });
}

// Remove tags, decode entities, collapse white space.
function text(html) {
  return decodeEntities(html.replace(/<br\s*\/?>/gi, ' ').replace(/<[^>]*>/g, ' ')).replace(/\s+/g, ' ').trim();
}

// The n8n Code node sandbox has no URL global. All hrefs on these pages are absolute paths or full URLs.
function absUrl(href) {
  const h = decodeEntities(href);
  if (/^https?:\/\//.test(h)) return h;
  return h.startsWith('/') ? SITE + h : `${SITE}/${h}`;
}

function isoToDate(iso) {
  const [y, m, d] = iso.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d, 12, 0, 0)); // 12:00 UTC: the calendar day stays the same in Europe/Berlin
}

// Fallback only: the card shows "01" and "Okt" but no <time datetime>.
function dayMonthToDate(day, mon, year, now) {
  const month = MONTHS[mon];
  if (!month) return null;
  if (year) return new Date(Date.UTC(year, month - 1, Number(day), 12));
  let date = new Date(Date.UTC(now.getUTCFullYear(), month - 1, Number(day), 12));
  if (date > now) date = new Date(Date.UTC(now.getUTCFullYear() - 1, month - 1, Number(day), 12));
  return date;
}

// Where does each item (card) start in the page? One marker per layout.
const CARD_MARKERS = {
  news: '<div class="col align-items-stretch mb-4">',
  tender: '<div class="article articletype-',
  event: '<div class="teaser-event',
};

function splitCards(html, layout) {
  const marker = CARD_MARKERS[layout];
  const starts = [];
  for (let i = html.indexOf(marker); i !== -1; i = html.indexOf(marker, i + marker.length)) starts.push(i);
  return starts.map((start, n) => {
    let end = n + 1 < starts.length ? starts[n + 1] : html.length;
    const nav = html.indexOf('<div class="page-navigation', start);
    if (nav !== -1 && nav < end) end = nav;
    return html.slice(start, end);
  });
}

// Value of an attribute inside the first <a ...> tag that has the given href.
function anchorAttr(card, href, attr) {
  const tags = card.match(/<a\s[^>]*>/g) || [];
  for (const tag of tags) {
    if (tag.includes(`href="${href}"`)) {
      const m = tag.match(new RegExp(`\\s${attr}="([^"]*)"`));
      if (m) return decodeEntities(m[1]).trim();
    }
  }
  return null;
}

function firstMatch(card, regex) {
  const m = card.match(regex);
  return m ? m[1] : null;
}

// cfg: { layout, hrefPart, ... } from config.js. Returns items in page order.
function parseItems(html, cfg, now = new Date()) {
  const seen = new Set();
  const items = [];
  const warnings = [];

  for (const card of splitCards(html, cfg.layout)) {
    const rawHref = firstMatch(card, new RegExp(`href="([^"]*${cfg.hrefPart}[^"]*)"`));
    if (!rawHref) continue;
    const link = absUrl(rawHref);
    if (seen.has(link)) continue; // image, title and "mehr Infos" point to the same target
    seen.add(link);

    const headline = firstMatch(card, /<span itemprop="headline">([\s\S]*?)<\/span>/);
    const title = anchorAttr(card, rawHref, 'title') || (headline ? text(headline) : link);

    const item = { title, link, guid: link, guidIsLink: true, description: '', date: null, city: null };

    if (cfg.layout === 'event') {
      parseEventFields(card, item, rawHref);
    } else {
      const iso = firstMatch(card, /<time datetime="(\d{4}-\d{2}-\d{2})"/);
      if (iso) {
        item.date = isoToDate(iso);
      } else {
        const day = firstMatch(card, /card-date-day[^>]*>(\d{1,2})</);
        const mon = firstMatch(card, /card-date-month[^>]*>([^<]+)</);
        const pathYear = firstMatch(link, /\/(\d{4})\//);
        if (day && mon) item.date = dayMonthToDate(day, mon.trim(), cfg.layout === 'news' && cfg.yearFromPath ? Number(pathYear) : null, now);
        warnings.push(`no <time datetime> for ${link}, used fallback`);
      }
      const desc = firstMatch(card, /<div itemprop="description">([\s\S]*?)<\/div>/);
      if (desc) {
        let d = text(desc);
        if (d.startsWith(title)) d = d.slice(title.length).trim(); // some teasers repeat the title
        item.description = d;
      }
      if (item.date && item.date.getTime() > now.getTime() + 86400000) warnings.push(`date in the future: ${link}`);
      if (cfg.yearFromPath) {
        const pathYear = firstMatch(link, /\/(\d{4})\//);
        if (item.date && pathYear && item.date.getUTCFullYear() !== Number(pathYear)) {
          warnings.push(`year differs from URL year (${pathYear}): ${link}`);
        }
      }
    }
    items.push(item);
  }
  return { items, warnings };
}

function parseEventFields(card, item, rawHref) {
  const id = firstMatch(rawHref, /-(\d+)$/);
  if (id) {
    item.guid = id;
    item.guidIsLink = false;
  }
  const headline = firstMatch(card, /<span itemprop="headline">([\s\S]*?)<\/span>/);
  const name = headline ? text(headline) : item.title;
  item.city = text(firstMatch(card, /<span class="card-place[^>]*>([\s\S]*?)<\/span>/) || '');
  const organizer = text(firstMatch(card, /<p class="organizer[^>]*>([\s\S]*?)<\/p>/) || '');
  const when = text(firstMatch(card, /<div class="card-body">([\s\S]*?)<\/div>/) || ''); // "Sonntag, 04.10.2026 09:00 Uhr - 13:00 Uhr"
  const day = when.match(/(\d{2})\.(\d{2})\.(\d{4})/);
  const time = when.match(/(\d{2}:\d{2}) Uhr/);
  const dateText = day ? `${day[1]}.${day[2]}.${day[3]}` : '';
  item.title = [item.city ? `[${item.city}]` : '', dateText, time ? time[1] : '', ].filter(Boolean).join(' ') + ` - ${name}`;
  item.description = [`Wann: ${when || 'unbekannt'}`, item.city ? `Ort: ${item.city}` : '', organizer ? `Veranstalter: ${organizer}` : '']
    .filter(Boolean).join('. ');
}

function filterByCity(items, ort) {
  const wanted = (ort || '').trim().toLowerCase();
  if (!wanted) return items;
  return items.filter((i) => (i.city || '').toLowerCase().includes(wanted));
}

// ---- RSS 2.0 ----

function stripInvalidXmlChars(s) {
  return s.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '');
}

function escapeXml(s) {
  return stripInvalidXmlChars(String(s))
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&apos;');
}

function cdata(s) {
  return `<![CDATA[${stripInvalidXmlChars(String(s)).replace(/]]>/g, ']]]]><![CDATA[>')}]]>`;
}

function buildRss({ feedUrl, channel, items, now = new Date() }) {
  const out = [];
  out.push('<?xml version="1.0" encoding="UTF-8"?>');
  out.push('<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom">');
  out.push('<channel>');
  out.push(`<title>${escapeXml(channel.title)}</title>`);
  out.push(`<link>${escapeXml(channel.link)}</link>`);
  out.push(`<description>${escapeXml(channel.description)}</description>`);
  out.push('<language>de</language>');
  out.push(`<lastBuildDate>${now.toUTCString()}</lastBuildDate>`);
  out.push(`<atom:link href="${escapeXml(feedUrl)}" rel="self" type="application/rss+xml"/>`);
  for (const i of items) {
    out.push('<item>');
    out.push(`<title>${escapeXml(i.title)}</title>`);
    out.push(`<link>${escapeXml(i.link)}</link>`);
    out.push(`<guid isPermaLink="${i.guidIsLink}">${escapeXml(i.guid)}</guid>`);
    if (i.pubDate) out.push(`<pubDate>${i.pubDate.toUTCString()}</pubDate>`);
    if (i.description) out.push(`<description>${cdata(i.description)}</description>`);
    out.push('</item>');
  }
  out.push('</channel>');
  out.push('</rss>');
  return out.join('\n') + '\n';
}


// Code node "Build feed": uses the functions from lib.js (pasted above this code by build.js).
// Input: the HTTP Request result. Output: { status, contentType, body, failed }.

const ctx = $('Config').first().json;
const store = $getWorkflowStaticData('global');
store.cache = store.cache || {};
store.seen = store.seen || {};

const RSS_TYPE = 'application/rss+xml; charset=utf-8';

// Failure: send the old XML if we have one (even if stale), else 502.
function fail(reason) {
  console.log(`[dithmarschen] ${ctx.feed}: ${reason}`);
  const stale = store.cache[ctx.cacheKey];
  if (stale) return [{ json: { failed: true, reason, status: 200, contentType: RSS_TYPE, body: stale.xml } }];
  return [{ json: { failed: true, reason, status: 502, contentType: 'text/plain; charset=utf-8', body: `Could not read the source page: ${reason}\n` } }];
}

const res = $input.first().json;
if (res.statusCode !== 200) return fail(`source answered HTTP ${res.statusCode}`);

let items, warnings;
try {
  ({ items, warnings } = parseItems(String(res.body ?? res.data ?? ''), ctx.cfg));
} catch (e) {
  return fail(`parse error: ${e.message}`);
}
if (items.length === 0) return fail('no items found, page layout may have changed');
for (const w of warnings) console.log(`[dithmarschen] ${ctx.feed}: ${w}`);

const now = new Date();

if (ctx.cfg.layout === 'event') {
  // Event date is not the publication date. Use the time we first saw the event.
  for (const i of items) {
    if (!store.seen[i.guid]) store.seen[i.guid] = now.toISOString();
    i.date = new Date(store.seen[i.guid]);
  }
  // Forget events that were not on page 1 for 60 days, so the map stays small.
  const onPage = new Set(items.map((i) => i.guid));
  for (const [guid, ts] of Object.entries(store.seen)) {
    if (!onPage.has(guid) && now - new Date(ts) > 60 * 86400000) delete store.seen[guid];
  }
  items = filterByCity(items, ctx.ort);
}

for (const i of items) i.pubDate = i.date;

const xml = buildRss({
  feedUrl: ctx.feedUrl,
  channel: { title: ctx.cfg.title, link: ctx.cfg.url, description: ctx.cfg.description },
  items,
  now,
});

store.cache[ctx.cacheKey] = { timestamp: now.getTime(), xml };
// Keep the cache small: drop the oldest entries.
const keys = Object.keys(store.cache).sort((a, b) => store.cache[a].timestamp - store.cache[b].timestamp);
for (const k of keys.slice(0, Math.max(0, keys.length - ctx.maxCacheEntries))) delete store.cache[k];

return [{ json: { failed: false, status: 200, contentType: RSS_TYPE, body: xml } }];
